package com.collisionmap;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Arrays;
import java.util.Locale;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

/** Click boxes and labels for doors, gates, shortcuts and anything else with a matching action. */
public class ObjectMarkerOverlay extends Overlay
{
    private final Client client;
    private final CollisionMapConfig config;
    private final ObjectTracker tracker;
    private final MapState state;

    // Config proxy calls are slow, so read the config only when it changed.
    private int snapshotVersion = -1;
    private boolean enabled, labels;
    private int radius;
    private Color colour, soft;
    private String[] filters = new String[0];

    @Inject
    private ObjectMarkerOverlay(Client client, CollisionMapConfig config, ObjectTracker tracker, MapState state)
    {
        this.client = client;
        this.config = config;
        this.tracker = tracker;
        this.state = state;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (snapshotVersion != state.configVersion())
        {
            snapshotVersion = state.configVersion();
            enabled = config.showObjects();
            labels = config.objectLabels();
            radius = config.drawRadius();
            colour = config.objectColor();
            soft = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), 35);
            filters = Arrays.stream(config.actionFilter().split(","))
                .map(f -> f.trim().toLowerCase(Locale.ROOT))
                .filter(f -> !f.isEmpty())
                .toArray(String[]::new);
        }
        if (!enabled || filters.length == 0)
        {
            return null;
        }

        WorldView wv = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        if (wv == null || player == null)
        {
            return null;
        }

        LocalPoint lp = player.getLocalLocation();
        int px = lp.getSceneX(), py = lp.getSceneY();
        int plane = wv.getPlane();

        graphics.setStroke(new BasicStroke(1.5f));
        FontMetrics fm = graphics.getFontMetrics();

        for (ObjectTracker.Tracked t : tracker.all())
        {
            // Cheap integer checks first; the composition lookup only happens for nearby objects.
            if (t.plane != plane || t.distanceTo(px, py) > radius)
            {
                continue;
            }
            ObjectComposition comp = t.current();
            if (comp == null)
            {
                continue;
            }
            String action = firstMatchingAction(comp.getActions());
            if (action == null)
            {
                continue;
            }

            Shape box = t.object.getClickbox();
            if (box != null)
            {
                graphics.setColor(soft);
                graphics.fill(box);
                graphics.setColor(colour);
                graphics.draw(box);
            }

            if (labels)
            {
                String name = comp.getName() == null ? "" : Text.removeTags(comp.getName());
                String text = (name.isEmpty() || "null".equals(name) ? "Object" : name) + " (" + action + ")";

                Point at = null;
                if (box != null)
                {
                    Rectangle b = box.getBounds();
                    at = new Point(b.x + b.width / 2 - fm.stringWidth(text) / 2, b.y - 4);
                }
                else
                {
                    at = t.object.getCanvasTextLocation(graphics, text, 0);
                }
                if (at != null)
                {
                    OverlayUtil.renderTextLocation(graphics, at, text, colour);
                }
            }
        }
        return null;
    }

    private String firstMatchingAction(String[] actions)
    {
        if (actions == null)
        {
            return null;
        }
        for (String a : actions)
        {
            if (a == null || a.isEmpty())
            {
                continue;
            }
            String lower = a.toLowerCase(Locale.ROOT);
            for (String f : filters)
            {
                if (lower.startsWith(f))
                {
                    return a;
                }
            }
        }
        return null;
    }
}

package com.collisionmap;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;

/**
 * Keeps the scene's interactable objects in a flat map so nothing has to walk the scene per frame.
 *
 * <p>Fed by the spawn/despawn/change events in {@link CollisionMapPlugin}, all of which arrive on
 * the client thread, as do the overlays that read this, so no locking is needed.
 *
 * <p>An object is kept if it has at least one action, or if it is an impostor (its actions depend on
 * a varbit, e.g. a shortcut that is only usable after a quest). Which of those count as
 * "interesting" is decided later, at draw time, so config changes apply instantly.
 */
@Singleton
public class ObjectTracker
{
    public enum Kind
    {
        WALL, GAME, DECORATIVE, GROUND
    }

    public static final class Tracked
    {
        public final TileObject object;
        public final Kind kind;
        public final int plane;
        /** Scene coordinates of the south-west tile of the object's footprint. */
        public final int sceneX, sceneY;
        public final int sizeX, sizeY;
        /** Wall objects only: orientation bitmask (1 = W, 2 = N, 4 = E, 8 = S). */
        public final int wallOrientation;
        private final ObjectComposition base;

        Tracked(TileObject object, Kind kind, int sceneX, int sceneY, int sizeX, int sizeY,
                int wallOrientation, ObjectComposition base)
        {
            this.object = object;
            this.kind = kind;
            this.plane = object.getPlane();
            this.sceneX = sceneX;
            this.sceneY = sceneY;
            this.sizeX = sizeX;
            this.sizeY = sizeY;
            this.wallOrientation = wallOrientation;
            this.base = base;
        }

        /** The composition currently in effect, following the impostor if there is one. May be null. */
        public ObjectComposition current()
        {
            return base.getImpostorIds() != null ? base.getImpostor() : base;
        }

        /** Chebyshev distance in tiles from a scene tile to the nearest tile of the footprint. */
        public int distanceTo(int x, int y)
        {
            int dx = x < sceneX ? sceneX - x : Math.max(0, x - (sceneX + sizeX - 1));
            int dy = y < sceneY ? sceneY - y : Math.max(0, y - (sceneY + sizeY - 1));
            return Math.max(dx, dy);
        }
    }

    private final Client client;
    private final Map<TileObject, Tracked> tracked = new HashMap<>();
    private int version;

    @Inject
    ObjectTracker(Client client)
    {
        this.client = client;
    }

    public Collection<Tracked> all()
    {
        return tracked.values();
    }

    /** Bumps whenever the set of tracked objects changes. */
    public int version()
    {
        return version;
    }

    public void clear()
    {
        if (!tracked.isEmpty())
        {
            tracked.clear();
            version++;
        }
    }

    public void add(GameObject o)
    {
        Point min = o.getSceneMinLocation();
        track(o, Kind.GAME, min.getX(), min.getY(), Math.max(1, o.sizeX()), Math.max(1, o.sizeY()), 0);
    }

    public void add(WallObject o)
    {
        LocalPoint lp = o.getLocalLocation();
        track(o, Kind.WALL, lp.getSceneX(), lp.getSceneY(), 1, 1, o.getOrientationA());
    }

    public void add(DecorativeObject o)
    {
        LocalPoint lp = o.getLocalLocation();
        track(o, Kind.DECORATIVE, lp.getSceneX(), lp.getSceneY(), 1, 1, 0);
    }

    public void add(GroundObject o)
    {
        LocalPoint lp = o.getLocalLocation();
        track(o, Kind.GROUND, lp.getSceneX(), lp.getSceneY(), 1, 1, 0);
    }

    public void remove(TileObject o)
    {
        if (o != null && tracked.remove(o) != null)
        {
            version++;
        }
    }

    private void track(TileObject o, Kind kind, int sx, int sy, int w, int h, int wallOrientation)
    {
        ObjectComposition comp = client.getObjectDefinition(o.getId());
        if (comp == null)
        {
            return;
        }
        if (comp.getImpostorIds() == null && !hasAnyAction(comp.getActions()))
        {
            return;
        }
        tracked.put(o, new Tracked(o, kind, sx, sy, w, h, wallOrientation, comp));
        version++;
    }

    static boolean hasAnyAction(String[] actions)
    {
        if (actions != null)
        {
            for (String a : actions)
            {
                if (a != null && !a.isEmpty())
                {
                    return true;
                }
            }
        }
        return false;
    }
}

package com.collisionmap;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;

/**
 * Answers "where can a door, gate or shortcut take me from here?" for {@link Reachability}.
 *
 * <p>Two sources:
 * <ul>
 *   <li>the bundled transport table (exact: origin tile, destination tile, object id), and</li>
 *   <li>live objects in the scene with an "Open" action (heuristic: it catches doors the table doesn't
 *       know about, but can't say where non-adjacent shortcuts lead).</li>
 * </ul>
 */
@Singleton
public class PassageIndex implements Reachability.Passages
{
    /**
     * A game object with an "Open" action only counts as a passage if its name looks like one.
     * Otherwise chests, cupboards and wardrobes would look like gates.
     */
    private static final Pattern GATE_NAME = Pattern.compile(
        "(?i)\\b(door|gate|doorway|barrier|portcullis|curtain|grill|grille|turnstile|stile|fence)s?\\b");

    private final Client client;
    private final ObjectTracker tracker;
    private final TransportData transportData;

    private final Map<Integer, int[]> dataFrom = new HashMap<>();
    private byte[][] openEdges = new byte[0][0];
    private boolean[][] openTiles = new boolean[0][0];

    @Inject
    PassageIndex(Client client, ObjectTracker tracker, TransportData transportData)
    {
        this.client = client;
        this.tracker = tracker;
        this.transportData = transportData;
    }

    private static int key(int x, int y)
    {
        return x << 8 | y;
    }

    /**
     * Rebuilds both sources for the current scene and plane.
     *
     * @param baseX world x of scene tile 0
     * @param baseY world y of scene tile 0
     * @param instance true inside instanced regions, where world coordinates don't map to the table
     */
    public void rebuild(int width, int height, int baseX, int baseY, int plane, boolean instance)
    {
        rebuildData(width, height, baseX, baseY, plane, instance);
        rebuildObjects(width, height, plane);
    }

    private void rebuildData(int width, int height, int baseX, int baseY, int plane, boolean instance)
    {
        dataFrom.clear();
        if (instance)
        {
            return;
        }

        Map<Integer, List<Integer>> tmp = new HashMap<>();
        for (TransportData.Transport t : transportData.all())
        {
            if (t.plane != plane)
            {
                continue;
            }
            int sx = t.ox - baseX, sy = t.oy - baseY, tx = t.dx - baseX, ty = t.dy - baseY;
            if (sx < 0 || sy < 0 || sx >= width || sy >= height
                || tx < 0 || ty < 0 || tx >= width || ty >= height)
            {
                continue;
            }
            if (!t.skillsMet(client))
            {
                continue;
            }
            List<Integer> list = tmp.computeIfAbsent(key(sx, sy), k -> new ArrayList<>(2));
            list.add(tx);
            list.add(ty);
        }
        for (Map.Entry<Integer, List<Integer>> e : tmp.entrySet())
        {
            dataFrom.put(e.getKey(), e.getValue().stream().mapToInt(Integer::intValue).toArray());
        }
    }

    private void rebuildObjects(int width, int height, int plane)
    {
        if (openEdges.length != width || (width > 0 && openEdges[0].length != height))
        {
            openEdges = new byte[width][height];
            openTiles = new boolean[width][height];
        }
        else
        {
            for (int x = 0; x < width; x++)
            {
                Arrays.fill(openEdges[x], (byte) 0);
                Arrays.fill(openTiles[x], false);
            }
        }

        for (ObjectTracker.Tracked t : tracker.all())
        {
            if (t.plane != plane || (t.kind != ObjectTracker.Kind.WALL && t.kind != ObjectTracker.Kind.GAME))
            {
                continue;
            }
            ObjectComposition comp = t.current();
            if (comp == null || !hasOpenAction(comp.getActions()))
            {
                continue;
            }

            if (t.kind == ObjectTracker.Kind.WALL)
            {
                // orientation bit 1 = W, 2 = N, 4 = E, 8 = S. Diagonal wall pieces (16+) are ignored.
                if (inBounds(t.sceneX, t.sceneY, width, height))
                {
                    int o = t.wallOrientation;
                    if ((o & 1) != 0) openEdges[t.sceneX][t.sceneY] |= 1 << Reachability.W;
                    if ((o & 2) != 0) openEdges[t.sceneX][t.sceneY] |= 1 << Reachability.N;
                    if ((o & 4) != 0) openEdges[t.sceneX][t.sceneY] |= 1 << Reachability.E;
                    if ((o & 8) != 0) openEdges[t.sceneX][t.sceneY] |= 1 << Reachability.S;
                }
            }
            else if (comp.getName() != null && GATE_NAME.matcher(comp.getName()).find())
            {
                for (int x = t.sceneX; x < t.sceneX + t.sizeX; x++)
                {
                    for (int y = t.sceneY; y < t.sceneY + t.sizeY; y++)
                    {
                        if (inBounds(x, y, width, height))
                        {
                            openTiles[x][y] = true;
                        }
                    }
                }
            }
        }
    }

    private static boolean inBounds(int x, int y, int w, int h)
    {
        return x >= 0 && y >= 0 && x < w && y < h;
    }

    /** "Open" only. A "Close" action means the door is already open, and open doors have no wall flag. */
    static boolean hasOpenAction(String[] actions)
    {
        if (actions != null)
        {
            for (String a : actions)
            {
                if (a != null && a.regionMatches(true, 0, "Open", 0, 4))
                {
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public int[] from(int x, int y)
    {
        return dataFrom.get(key(x, y));
    }

    @Override
    public boolean canOpenEdge(int x, int y, int dir)
    {
        if (openEdges.length == 0)
        {
            return false;
        }
        int w = openEdges.length, h = openEdges[0].length;
        if (inBounds(x, y, w, h) && (openEdges[x][y] >> dir & 1) != 0)
        {
            return true;
        }
        int nx = x + Reachability.DX[dir], ny = y + Reachability.DY[dir];
        return inBounds(nx, ny, w, h) && (openEdges[nx][ny] >> Reachability.opposite(dir) & 1) != 0;
    }

    @Override
    public boolean canOpenTile(int x, int y)
    {
        return openTiles.length > 0 && inBounds(x, y, openTiles.length, openTiles[0].length) && openTiles[x][y];
    }
}

package com.collisionmap;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import net.runelite.api.CollisionDataFlag;

/**
 * Flood fill over the scene's collision flags, starting at the player's tile.
 *
 * <p>The fill works in "hops". Hop 0 is everything you can walk to right now. Each door, gate or
 * shortcut that leads out of that area is a passage; hop 1 is everything on the far side of those
 * passages, hop 2 the far side of the passages found in hop 1, and so on up to {@code maxHops}.
 * A tile's {@link Result#tier} is {@code hop + 1}, so 0 ({@link #NONE}) means "not reached".
 *
 * <p>Only cardinal steps are needed. OSRS only allows a diagonal step when both of the adjacent
 * cardinal steps are also open, so a cardinal fill reaches exactly the same tiles.
 *
 * <p>No RuneLite client objects are used here, only the flag array, so this is cheap to unit test.
 * It is O(scene tiles) and is meant to run when something changes, not every frame.
 */
public final class Reachability
{
    public static final byte NONE = 0;

    // Directions. Scene y grows to the north, matching the collision flags.
    public static final int N = 0, E = 1, S = 2, W = 3;
    public static final int[] DX = {0, 1, 0, -1};
    public static final int[] DY = {1, 0, -1, 0};

    // Flag that blocks leaving a tile in direction d, and flag that blocks entering from that side.
    private static final int[] OUT = {
        CollisionDataFlag.BLOCK_MOVEMENT_NORTH, CollisionDataFlag.BLOCK_MOVEMENT_EAST,
        CollisionDataFlag.BLOCK_MOVEMENT_SOUTH, CollisionDataFlag.BLOCK_MOVEMENT_WEST};
    private static final int[] IN = {
        CollisionDataFlag.BLOCK_MOVEMENT_SOUTH, CollisionDataFlag.BLOCK_MOVEMENT_WEST,
        CollisionDataFlag.BLOCK_MOVEMENT_NORTH, CollisionDataFlag.BLOCK_MOVEMENT_EAST};

    public static int opposite(int dir)
    {
        return dir ^ 2;
    }

    /** True if movement between (x,y) and its neighbour in direction {@code dir} is blocked by a wall flag. */
    public static boolean edgeBlocked(int[][] flags, int x, int y, int dir)
    {
        if ((flags[x][y] & OUT[dir]) != 0)
        {
            return true;
        }
        int nx = x + DX[dir], ny = y + DY[dir];
        return nx >= 0 && ny >= 0 && nx < flags.length && ny < flags[0].length
            && (flags[nx][ny] & IN[dir]) != 0;
    }

    public static boolean fullyBlocked(int flag)
    {
        return (flag & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0;
    }

    /** Where passages come from. Implemented by {@link PassageIndex}. */
    public interface Passages
    {
        Passages NONE = new Passages()
        {
            @Override
            public int[] from(int x, int y)
            {
                return null;
            }

            @Override
            public boolean canOpenEdge(int x, int y, int dir)
            {
                return false;
            }

            @Override
            public boolean canOpenTile(int x, int y)
            {
                return false;
            }
        };

        /** Data-table passages that start on this tile, as a flat {@code [toX, toY, toX, toY...]}, or null. */
        int[] from(int x, int y);

        /** True if the wall on the edge leaving (x,y) towards {@code dir} is a door/gate you can open. */
        boolean canOpenEdge(int x, int y, int dir);

        /** True if this fully blocked tile is a gate-like object you can open and walk through. */
        boolean canOpenTile(int x, int y);
    }

    public static final class Link
    {
        public final int fromX, fromY, toX, toY;

        Link(int fromX, int fromY, int toX, int toY)
        {
            this.fromX = fromX;
            this.fromY = fromY;
            this.toX = toX;
            this.toY = toY;
        }

        /** Adjacent links are drawn as a coloured edge, longer ones as two highlighted tiles and a line. */
        public boolean adjacent()
        {
            return Math.abs(fromX - toX) + Math.abs(fromY - toY) == 1;
        }
    }

    public static final class Result
    {
        /** 0 = not reached, otherwise hop + 1. */
        public final byte[][] tier;
        /** Per tile bitmask (1 << dir) of edges that are passages, so the overlay can colour them. */
        public final byte[][] passageEdges;
        public final List<Link> links;

        Result(byte[][] tier, byte[][] passageEdges, List<Link> links)
        {
            this.tier = tier;
            this.passageEdges = passageEdges;
            this.links = links;
        }

        public boolean reached(int x, int y)
        {
            return x >= 0 && y >= 0 && x < tier.length && y < tier[0].length && tier[x][y] != NONE;
        }
    }

    public static Result compute(int[][] flags, int startX, int startY, int maxHops, Passages passages)
    {
        return new Reachability(flags, passages, maxHops).run(startX, startY);
    }

    // ------------------------------------------------------------------ implementation

    private final int[][] flags;
    private final Passages passages;
    private final int maxHops;
    private final int w, h;
    private final byte[][] tier;
    private final byte[][] passageEdges;
    private final List<Link> links = new ArrayList<>();
    private final Set<Long> seenLinks = new HashSet<>();

    private Reachability(int[][] flags, Passages passages, int maxHops)
    {
        this.flags = flags;
        this.passages = passages;
        this.maxHops = Math.max(0, maxHops);
        this.w = flags.length;
        this.h = w == 0 ? 0 : flags[0].length;
        this.tier = new byte[w][h];
        this.passageEdges = new byte[w][h];
    }

    private Result run(int startX, int startY)
    {
        if (startX < 0 || startY < 0 || startX >= w || startY >= h)
        {
            return new Result(tier, passageEdges, links);
        }

        int[] queue = new int[w * h];
        List<Integer> seeds = new ArrayList<>();
        seeds.add(startX * h + startY);

        for (int hop = 0; hop <= maxHops && !seeds.isEmpty(); hop++)
        {
            byte t = (byte) (hop + 1);
            boolean canSeed = hop < maxHops;
            int head = 0, tail = 0;

            for (int s : seeds)
            {
                int x = s / h, y = s % h;
                if (tier[x][y] == NONE)
                {
                    tier[x][y] = t;
                    queue[tail++] = s;
                }
            }
            List<Integer> next = new ArrayList<>();

            while (head < tail)
            {
                int c = queue[head++];
                int x = c / h, y = c % h;

                // Passages from the transport table that start on this tile.
                int[] dp = passages.from(x, y);
                if (dp != null)
                {
                    for (int i = 0; i + 1 < dp.length; i += 2)
                    {
                        int tx = dp[i], ty = dp[i + 1];
                        if (tx < 0 || ty < 0 || tx >= w || ty >= h || fullyBlocked(flags[tx][ty]))
                        {
                            continue;
                        }
                        addLink(x, y, tx, ty);
                        if (canSeed && tier[tx][ty] == NONE)
                        {
                            next.add(tx * h + ty);
                        }
                    }
                }

                for (int d = 0; d < 4; d++)
                {
                    int nx = x + DX[d], ny = y + DY[d];
                    if (nx < 0 || ny < 0 || nx >= w || ny >= h)
                    {
                        continue;
                    }

                    boolean nFull = fullyBlocked(flags[nx][ny]);
                    boolean wall = edgeBlocked(flags, x, y, d);

                    if (!nFull && !wall)
                    {
                        if (tier[nx][ny] == NONE)
                        {
                            tier[nx][ny] = t;
                            queue[tail++] = nx * h + ny;
                        }
                        continue;
                    }

                    if (!nFull)
                    {
                        // Only a wall in the way: a door or gate on this edge?
                        if (passages.canOpenEdge(x, y, d))
                        {
                            addLink(x, y, nx, ny);
                            if (canSeed && tier[nx][ny] == NONE)
                            {
                                next.add(nx * h + ny);
                            }
                        }
                    }
                    else if (passages.canOpenTile(nx, ny))
                    {
                        // A gate-like object occupies the next tile: land on the tile beyond it.
                        int cx = nx + DX[d], cy = ny + DY[d];
                        if (cx >= 0 && cy >= 0 && cx < w && cy < h && !fullyBlocked(flags[cx][cy]))
                        {
                            addLink(x, y, cx, cy);
                            if (canSeed && tier[cx][cy] == NONE)
                            {
                                next.add(cx * h + cy);
                            }
                        }
                    }
                }
            }
            seeds = next;
        }

        return new Result(tier, passageEdges, links);
    }

    private void addLink(int fx, int fy, int tx, int ty)
    {
        int dx = tx - fx, dy = ty - fy;
        if (Math.abs(dx) + Math.abs(dy) == 1)
        {
            int d = dx == 1 ? E : dx == -1 ? W : dy == 1 ? N : S;
            int bit = 1 << d;
            if ((passageEdges[fx][fy] & bit) != 0)
            {
                return;
            }
            passageEdges[fx][fy] |= bit;
            passageEdges[tx][ty] |= 1 << opposite(d);
            links.add(new Link(fx, fy, tx, ty));
            return;
        }

        long a = (long) fx * h + fy, b = (long) tx * h + ty;
        long key = Math.min(a, b) << 32 | Math.max(a, b);
        if (seenLinks.add(key))
        {
            links.add(new Link(fx, fy, tx, ty));
        }
    }
}

package com.collisionmap;

/**
 * Turns a row of projected tile corners into as few straight lines as possible.
 *
 * <p>A wall along a row of tiles is many unit edges, but on flat ground they all project onto one
 * straight screen line. Java2D's cost goes up with segment count, so this merges consecutive edges
 * whenever every intermediate corner stays within a pixel or so of the straight line between the ends.
 * On sloped terrain the corners bend away from the line, the run is split there, and the line still
 * follows the ground.
 *
 * <p>Pure geometry with no RuneLite types, so it can be unit tested on its own.
 */
final class RunMerger
{
    interface Sink
    {
        void line(int x1, int y1, int x2, int y2);
    }

    /** Max squared distance, in pixels, an intermediate corner may sit from the merged line. */
    static final double TOLERANCE_SQ = 2.25;

    private final int[] midX = new int[512];
    private final int[] midY = new int[512];

    /**
     * @param xs, ys canvas position of each corner along the run, in order
     * @param ok     false where a corner couldn't be projected (behind the camera); the run is broken there
     * @param n      number of corners (edges + 1)
     * @return number of lines emitted
     */
    int merge(int[] xs, int[] ys, boolean[] ok, int n, Sink sink)
    {
        int lines = 0;
        boolean haveStart = false, haveEnd = false;
        int sx = 0, sy = 0, ex = 0, ey = 0;
        int mids = 0;

        for (int k = 0; k < n; k++)
        {
            if (!ok[k])
            {
                if (haveEnd)
                {
                    sink.line(sx, sy, ex, ey);
                    lines++;
                }
                haveStart = false;
                haveEnd = false;
                mids = 0;
                continue;
            }

            int x = xs[k], y = ys[k];
            if (!haveStart)
            {
                sx = x;
                sy = y;
                haveStart = true;
                haveEnd = false;
                mids = 0;
                continue;
            }
            if (!haveEnd)
            {
                ex = x;
                ey = y;
                haveEnd = true;
                continue;
            }

            // Try to stretch start..end to start..(x,y). The old end becomes an intermediate corner.
            if (mids < midX.length - 1 && fits(sx, sy, x, y, ex, ey, mids))
            {
                midX[mids] = ex;
                midY[mids] = ey;
                mids++;
                ex = x;
                ey = y;
            }
            else
            {
                sink.line(sx, sy, ex, ey);
                lines++;
                sx = ex;
                sy = ey;
                ex = x;
                ey = y;
                mids = 0;
            }
        }

        if (haveEnd)
        {
            sink.line(sx, sy, ex, ey);
            lines++;
        }
        return lines;
    }

    /** True if all stored intermediates and the current end lie close enough to the line start..(x,y). */
    private boolean fits(int sx, int sy, int x, int y, int ex, int ey, int mids)
    {
        double dx = x - sx, dy = y - sy;
        double len2 = dx * dx + dy * dy;
        if (len2 == 0)
        {
            return false;
        }
        double limit = TOLERANCE_SQ * len2;
        for (int i = 0; i < mids; i++)
        {
            double c = dx * (midY[i] - sy) - dy * (midX[i] - sx);
            if (c * c > limit)
            {
                return false;
            }
        }
        double c = dx * (ey - sy) - dy * (ex - sx);
        return c * c <= limit;
    }
}

package com.collisionmap;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Singleton;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;

/**
 * Same-plane doors, gates, crossings and shortcuts, loaded from transports.tsv.
 *
 * <p>The table is derived from the Shortest Path plugin's transport data (BSD 2-Clause, see
 * transports.NOTICE.txt). Rows that change plane or travel more than 52 tiles were dropped, since a
 * flood fill on one plane can't use them anyway.
 */
@Slf4j
@Singleton
public class TransportData
{
    public static final class Transport
    {
        public final int ox, oy, plane, dx, dy;
        public final String option, target;
        public final int objectId;
        private final Skill[] skills;
        private final int[] levels;

        Transport(int ox, int oy, int plane, int dx, int dy, String option, String target, int objectId,
                  Skill[] skills, int[] levels)
        {
            this.ox = ox;
            this.oy = oy;
            this.plane = plane;
            this.dx = dx;
            this.dy = dy;
            this.option = option;
            this.target = target;
            this.objectId = objectId;
            this.skills = skills;
            this.levels = levels;
        }

        /** Only skill levels are checked. Quests, items and varbits are not. */
        public boolean skillsMet(Client client)
        {
            for (int i = 0; i < skills.length; i++)
            {
                if (client.getRealSkillLevel(skills[i]) < levels[i])
                {
                    return false;
                }
            }
            return true;
        }
    }

    private List<Transport> transports = Collections.emptyList();

    public List<Transport> all()
    {
        return transports;
    }

    public void load()
    {
        List<Transport> out = new ArrayList<>();
        try (InputStream in = TransportData.class.getResourceAsStream("transports.tsv"))
        {
            if (in == null)
            {
                log.warn("transports.tsv not found on the classpath, shortcut data disabled");
                return;
            }
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String line;
            while ((line = reader.readLine()) != null)
            {
                if (line.isEmpty() || line.charAt(0) == '#')
                {
                    continue;
                }
                Transport t = parse(line);
                if (t != null)
                {
                    out.add(t);
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to read transports.tsv", e);
        }
        transports = out;
        log.debug("Loaded {} transports", out.size());
    }

    private static Transport parse(String line)
    {
        // ox oy plane dx dy option target objectId skills
        String[] c = line.split("\t", -1);
        if (c.length < 8)
        {
            return null;
        }
        try
        {
            int ox = Integer.parseInt(c[0]), oy = Integer.parseInt(c[1]), plane = Integer.parseInt(c[2]);
            int dx = Integer.parseInt(c[3]), dy = Integer.parseInt(c[4]);
            if (ox == dx && oy == dy)
            {
                return null;
            }

            List<Skill> skills = new ArrayList<>();
            List<Integer> levels = new ArrayList<>();
            if (c.length > 8 && !c[8].isEmpty())
            {
                for (String token : c[8].split(";"))
                {
                    // "25 Agility". Anything else (e.g. "Max Quest") is ignored, i.e. treated as met.
                    String[] parts = token.trim().split(" ", 2);
                    if (parts.length != 2)
                    {
                        continue;
                    }
                    try
                    {
                        levels.add(Integer.parseInt(parts[0]));
                        skills.add(Skill.valueOf(parts[1].trim().toUpperCase()));
                    }
                    catch (IllegalArgumentException ignored)
                    {
                        if (levels.size() > skills.size())
                        {
                            levels.remove(levels.size() - 1);
                        }
                    }
                }
            }

            return new Transport(ox, oy, plane, dx, dy, c[5], c[6], Integer.parseInt(c[7]),
                skills.toArray(new Skill[0]), levels.stream().mapToInt(Integer::intValue).toArray());
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }
}

